// Demo data is generated by running the real workflow engine, so every record has a consistent history.
import * as E from './engine.js';
import { makeCtx, SETTINGS_DEFAULT } from './ctx.js';
import { userById, DEPT_HEAD } from './data/people.js';

export const SCHEMA_VERSION = 5;
const DEF = {
  validation: { process: 'No', cleaning: 'No', equipment: 'No' }, analytical: { method: 'No', equipment: 'No' }, stability: { required: 'No' }, computer: { validation: 'No' },
  safety: { operator: 'No', environment: 'No' }, training: { departments: ['QAD'], trainingType: 'Read and Understand' }, qad: { stabilityProtocol: 'No', vendor: 'No', qualityAgreement: 'No' },
};
const WHO = { validation: 'u_rajesh', analytical: 'u_saurabh', stability: 'u_saurabh', computer: 'u_vivek', safety: 'u_kavita', qad: 'u_neha' };
const REG0 = { andaStatus: 'Not Applicable', applicable: 'Not Applicable', reporting: [], regActionRequired: false, clientRequired: false, comments: 'No regulatory filing impact.' };
const RISK0 = { q1a: 'No', q1b: 'No', q1c: 'No', q1d: 'No', q2a: 'No' };

export function buildSeed(base = new Date()) {
  const counters = { cc: {}, draft: 2480 };
  const settings = { ...SETTINGS_DEFAULT };
  const day = (n, h = 10) => { const d = E.addDays(base, n); d.setUTCHours(h, 5 * (Math.abs(n) % 11), 0, 0); return d > base ? new Date(base.getTime() - 60000 * (2 + (Math.abs(n * 7 + h) % 40))) : d; };
  const mk = (uid, n, h) => makeCtx(userById(uid), { settings, counters, now: day(n, h) });
  const fut = (n) => E.isoDate(E.addDays(base, n));
  const chg = (c, p, j) => [{ sno: 1, current: c, proposed: p, justification: j }];

  function build(spec, upTo, start) {
    let t = -start; const step = () => (t += 1);
    const init = spec.initiator;
    let r = E.createDraft(mk(init, t, 9), spec.form);
    if (upTo === 'draft') return r;
    r = E.submit(r, mk(init, t, 11));
    if (upTo === 'pend_endorse') return r;
    r = E.endorse(r, mk(DEPT_HEAD[r.department], step(), 10), { decision: 'endorse', comment: 'Endorsed. Business need confirmed.' });
    if (upTo === 'pend_screen') return r;
    r = E.screen(r, mk('u_priya', step(), 11), { decision: 'accept', checks: { complete: true, justified: true, noDuplicate: true }, remarks: '' });
    const plan = spec.assess || {}; step();
    const keys = Object.keys(DEF);
    const cl = (upTo === 'clarify' || upTo === 'reendorse' || upTo === 'round2') ? 'analytical' : null;
    const doAssess = (k, i) => {
      const p = plan[k] || {};
      const uid = k === 'training' ? DEPT_HEAD[r.department] : WHO[k];
      r = E.assess(r, mk(uid, t + (i % 3 === 0 ? 0 : 1), 9 + i), k, { decision: p.decision || 'accept', answers: { ...DEF[k], ...(p.answers || {}) }, comments: p.comments || '', actions: p.actions });
    };
    keys.forEach((k, i) => { if (k !== cl && !(spec.skip || []).includes(k)) doAssess(k, i); });
    if (cl) {
      r = E.assess(r, mk('u_saurabh', t + 1, 14), cl, { decision: 'clarify', clarificationText: spec.clarify, answers: DEF[cl] });
      if (upTo === 'clarify') return r;
      r = E.respondClarification(r, mk(init, t + 2, 10), { text: 'Updated the change table as requested.', changes: spec.fixChanges || r.changes });
      if (upTo === 'reendorse') return r;
      r = E.endorse(r, mk(DEPT_HEAD[r.department], t + 2, 15), { decision: 'endorse', comment: 'Re-endorsed after correction.' });
      return r; // round 2 in progress
    }
    if (upTo === 'assess') return r;
    if (upTo === 'reg-wait') return r;
    t += 2;
    r = E.regulatory(r, mk('u_meera', t, 11), spec.reg || REG0);
    if (spec.clientEvidenceAt !== undefined) r = E.uploadClientEvidence(r, mk(spec.reg.clientOwnerId, t + spec.clientEvidenceAt, 15), { fileName: spec.clientFile, reviewedBy: spec.clientReviewer, comment: 'Approved.' });
    t += 1;
    (spec.extraActions || []).forEach((a) => { r = E.addAction(r, mk(init, t, 10), a); });
    if (upTo === 'consol') return r;
    r = E.consolidate(r, mk(init, t, 14), { decision: 'submit' });
    if (upTo === 'qa') return r;
    t += 1;
    r = E.qaApprove(r, mk('u_priya', t, 11), { decision: 'approve', answers: spec.risk || RISK0, comments: 'Risk assessed and acceptable with the listed actions.', dueDate: E.isoDate(E.addDays(day(t), 60)), raReviewed: true });
    (spec.impl || []).forEach((u) => { t += u.after; const act = r.actions.find((a) => a.id === u.id); r = E.updateAction(r, mk(act.ownerId, t, 13), u.id, { status: u.status, comment: u.comment, evidenceName: u.evidence, evidenceNA: u.na }); });
    (spec.extra2 || []).forEach((f) => { r = f(r, mk); });
    if (upTo === 'impl') return r;
    t += 1; r = E.verify(r, mk(init, t, 10), { sopNumber: spec.sopNumber });
    if (upTo === 'closeout') return r;
    t += 1; const sug = E.suggestCloseout(r);
    return E.closeout(r, mk('u_priya', t, 12), { decision: 'close', answers: { c1: 'Yes', c2: 'Yes', c3: 'Yes', c4: 'No', c5: 'No', c6: 'Yes', c7: sug.c7, c8: sug.c8 || 'Yes' }, comment: 'All requirements satisfied.' });
  }
  const F = (o) => ({ currentDoc: '', proposedDoc: '', layoutPlan: false, ...o });
  const recs = [];

  recs.push(build({ initiator: 'u_pooja', form: F({ title: 'Revise HPLC assay method TM-021 – change mobile phase buffer', type: 'Test Method', currentDoc: 'TM-021 v03', proposedDoc: 'TM-021 v04', changes: chg('Mobile phase uses phosphate buffer pH 3.0, 18 min runtime.', 'Phosphate buffer pH 2.8, 12 min runtime.', 'Improves peak symmetry and reduces runtime.') }),
    assess: { analytical: { decision: 'accept_action', answers: { method: 'Yes', equipment: 'No' }, comments: 'Method validation required.', actions: [{ description: 'Execute method validation for revised TM-021', ownerId: 'u_saurabh', due: fut(-30) }] }, training: { decision: 'accept_action', answers: { departments: ['QCS'], trainingType: 'Read and Understand' }, actions: [{ description: 'Train QC analysts on TM-021 v04', ownerId: 'u_pooja', due: fut(-20) }] } },
    impl: [{ id: 'ACT-01', after: 8, status: 'Completed', comment: 'Validation report approved.', evidence: 'TM-021_validation_report.pdf' }, { id: 'ACT-02', after: 4, status: 'Completed', comment: 'Training completed.', evidence: 'TM-021_training_attendance.pdf' }] }, 'closed', 70));

  recs.push(build({ initiator: 'u_ananya', form: F({ title: 'Replace end-of-life vision cameras on Packaging Line 3', type: 'Equipment/Facility/Utility', currentDoc: 'EQ-PKG-003', proposedDoc: 'EQ-PKG-003A', changes: [{ sno: 1, current: 'Discontinued cameras give frequent false rejects.', proposed: 'Install new cameras with audit trail.', justification: 'Removes obsolescence risk.' }, { sno: 2, current: 'Manual batch reconciliation.', proposed: 'Automated electronic batch reconciliation.', justification: 'Improves data integrity and line speed.' }] }),
    assess: { validation: { decision: 'accept_action', answers: { process: 'No', cleaning: 'No', equipment: 'Yes' }, comments: 'Equipment qualification required.', actions: [{ description: 'Execute IQ/OQ for the new vision system', ownerId: 'u_nikhil', due: fut(4) }] }, computer: { decision: 'accept_action', answers: { validation: 'Yes' }, actions: [{ description: 'Validate vision software (audit trail, access control)', ownerId: 'u_vivek', due: fut(-3) }] }, training: { decision: 'accept_action', answers: { departments: ['OPS', 'QAD'], trainingType: 'On-The-Job Training' }, actions: [{ description: 'Train line operators on the new procedure', ownerId: 'u_karan', due: fut(5) }] } },
    reg: { andaStatus: 'Not Applicable', applicable: 'Not Applicable', reporting: [], regActionRequired: false, clientRequired: true, clientName: 'Veridian Therapeutics', clientOwnerId: 'u_sonal', clientDue: fut(-5), comments: 'Client notification required.' }, clientEvidenceAt: 1, clientFile: 'Veridian_approval_signed.pdf', clientReviewer: 'Dr. A. Fischer',
    extraActions: [{ description: 'Update the line clearance checklist', ownerId: 'u_karan', due: fut(3) }], risk: { ...RISK0, q1b: 'Yes', q1d: 'Yes' },
    impl: [{ id: 'ACT-05', after: 3, status: 'Completed', comment: 'Checklist approved.', evidence: 'Line_clearance_checklist_rev2.pdf' }, { id: 'ACT-01', after: 1, status: 'In Progress', comment: 'IQ done; OQ scheduled.' }],
    extra2: [(r, mk) => E.requestExtension(r, mk('u_ananya', -1, 9), { days: 30, reason: 'Vendor OQ support is delayed by two weeks.' }), (r, mk) => E.decideExtension(r, mk('u_vikram', -1, 15), r.extensions[0].id, { decision: 'approve', comment: 'Valid reason – passed to QAD HOD.' }), (r, mk) => E.requestAmendment(r, mk('u_ananya', -1, 16), { description: 'Add recalibration schedule for the new cameras', reason: 'Not defined in the original plan.', ownerId: 'u_nikhil', due: fut(4) })] }, 'impl', 62));

  recs.push(build({ initiator: 'u_ananya', form: F({ title: 'Revise SOP-MFG-012 – Line clearance procedure', type: 'SOP', currentDoc: 'SOP-MFG-012 v04', proposedDoc: 'SOP-MFG-012 v05', changes: chg('SOP omits clearance of printed packaging components.', 'Add clearance steps and a second-person check.', 'Closes an audit observation.') }),
    assess: { training: { decision: 'accept_action', answers: { departments: ['OPS', 'QAD'], trainingType: 'Read and Understand' }, actions: [{ description: 'Train staff on SOP-MFG-012 v05', ownerId: 'u_karan', due: fut(-6) }] } }, extraActions: [{ description: 'Issue SOP v05 as effective and retrieve old copies', ownerId: 'u_priya', due: fut(-8) }],
    impl: [{ id: 'ACT-02', after: 6, status: 'Completed', comment: 'SOP v05 effective.', evidence: 'SOP-MFG-012_v05_effective.pdf' }, { id: 'ACT-01', after: 1, status: 'Completed', comment: 'Training completed for 24 staff.', evidence: 'Training_attendance.pdf' }], sopNumber: 'SOP-MFG-012 v05 (approved by QAD)' }, 'closeout', 36));

  recs.push(build({ initiator: 'u_ananya', form: F({ title: 'Change supplier of primary packaging film', type: 'Vendor', currentDoc: 'FilmPack Ltd (PK-110)', proposedDoc: 'AlphaFoil Ltd (PK-110)', changes: chg('Single-source supplier with delivery delays.', 'Qualify AlphaFoil Ltd as second supplier.', 'Secures supply continuity.') }),
    assess: { qad: { decision: 'accept_action', answers: { stabilityProtocol: 'Yes', vendor: 'Yes', qualityAgreement: 'Yes' }, actions: [{ description: 'Complete vendor qualification audit for AlphaFoil Ltd', ownerId: 'u_priya', due: fut(30) }] } },
    reg: { andaStatus: 'Approved', applicable: 'Applicable', reporting: ['Supplement-Changes being affected in 30 days'], reference: 'ANDA 214567', regActionRequired: true, clientRequired: true, clientName: 'Veridian Therapeutics', clientOwnerId: 'u_sonal', clientDue: fut(10), actions: [{ description: 'File the CBE-30 supplement for ANDA 214567', ownerId: 'u_meera', due: fut(25) }] } }, 'qa', 12));

  recs.push(build({ initiator: 'u_pooja', form: F({ title: 'Upgrade environmental monitoring software to v6.2', type: 'Computer System', currentDoc: 'EMS v5.4', proposedDoc: 'EMS v6.2', changes: chg('v5.4 is out of vendor support.', 'Upgrade to v6.2 with revalidation.', 'Vendor support ends this year.') }), assess: { computer: { decision: 'accept_action', answers: { validation: 'Yes' }, actions: [{ description: 'Validate EMS v6.2 (IQ/OQ/PQ)', ownerId: 'u_vivek', due: fut(40) }] } } }, 'consol', 9));
  recs.push(build({ initiator: 'u_pooja', form: F({ title: 'Tighten assay limit of raw material RM-045', type: 'Specification', currentDoc: 'SPEC-RM-045 v02', proposedDoc: 'SPEC-RM-045 v03', changes: chg('Assay limit 95.0–105.0%.', 'Assay limit 98.0–102.0%.', 'Supplier data show consistent results.') }) }, 'reg-wait', 7));
  recs.push(build({ initiator: 'u_ananya', form: F({ title: 'Update batch record BMR-114 for tablet compression', type: 'Batch Record', currentDoc: 'BMR-114 v06', proposedDoc: 'BMR-114 v07', changes: chg('Hardness checked hourly.', 'Check every 30 minutes for the first two hours.', 'Detects compression drift earlier.') }), clarify: 'Which hardness tester and calibration status will be used for the 30-minute checks?' }, 'clarify', 4));
  recs.push(build({ initiator: 'u_pooja', form: F({ title: 'Update stability protocol SP-009 storage conditions', type: 'Protocol/Report', currentDoc: 'SP-009 v01', proposedDoc: 'SP-009 v02', changes: chg('Samples stored at 25°C/60% RH only.', 'Add 30°C/65% RH intermediate condition.', 'Required by updated guideline.') }), clarify: 'Please state the sample pull points for the new condition.' }, 'reendorse', 5));
  recs.push(build({ initiator: 'u_ananya', form: F({ title: 'Add alkaline detergent to the CIP cycle of Granulator GR-02', type: 'Other', otherType: 'Cleaning procedure', currentDoc: 'CLN-GR-02 v03', proposedDoc: 'CLN-GR-02 v04', changes: chg('Purified-water rinse only.', 'Alkaline wash then water rinse.', 'Improves residue removal.') }), clarify: 'Confirm the detergent concentration and rinse validation.', fixChanges: [{ sno: 1, current: 'Purified-water rinse only.', proposed: 'Alkaline wash (0.5%) then water rinse with rinse-water TOC test.', justification: 'Improves residue removal; rinse validated by TOC.' }] }, 'round2', 8));
  recs.push(build({ initiator: 'u_pooja', form: F({ title: 'Relocate the reserve sample cabinet to the new QC annex', type: 'Equipment/Facility/Utility', changes: chg('Cabinet in old store.', 'Move to the QC annex.', 'More space and better control.') }) }, 'pend_screen', 2));
  recs.push(build({ initiator: 'u_ananya', form: F({ title: 'Revise label artwork for Product M-500', type: 'Labeling Component', changes: chg('Old pack artwork.', 'New artwork with updated storage statement.', 'Regulatory update.') }) }, 'pend_endorse', 1));
  recs.push(build({ initiator: 'u_ananya', form: F({ title: 'Relocate packaging scale', type: 'Equipment/Facility/Utility', changes: [{ sno: 1, current: '', proposed: '', justification: '' }] }) }, 'draft', 0));

  return { schema: SCHEMA_VERSION, counters, delegations: [], settings, records: recs.reverse(), admin: [{ id: 'ad-1', at: day(-60).toISOString(), actor: 'Rohit Sinha', action: 'Demo data initialised', detail: 'System baseline created.' }], seededAt: base.toISOString() };
}
